using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;
namespace CodexOutTransfer {
 [InitializeOnLoad]public static class OutMainCameraSetup {
  const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",Phase="OutMainSetup.Phase",Data="OutMainSetup.Data";static double started;
  [Serializable]class Snapshot {public string scene;public Vector3 position,scale;public Quaternion rotation;public float fov,near,far,orthoSize;public bool ortho,wasPlaying;}
  static OutMainCameraSetup(){EditorApplication.playModeStateChanged+=StateChanged;if(SessionState.GetString(Phase,"")=="apply"&&!EditorApplication.isPlayingOrWillChangePlaymode)EditorApplication.delayCall+=Apply;if(SessionState.GetString(Phase,"")=="verify"&&EditorApplication.isPlaying)StartCheck();}
  static Camera Find(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.IsValid()||!s.isLoaded)throw new Exception("out must be loaded");return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.name=="Camera"&&c.transform.parent&&c.transform.parent.name=="xiangjipingtai");}
  [MenuItem("Tools/Out Scene Transfer/Set Selected Camera As Main")]
  public static void Run(){try{var c=Find();var snapshot=new Snapshot{scene=c.gameObject.scene.path,position=c.transform.position,rotation=c.transform.rotation,scale=c.transform.localScale,fov=c.fieldOfView,near=c.nearClipPlane,far=c.farClipPlane,ortho=c.orthographic,orthoSize=c.orthographicSize,wasPlaying=EditorApplication.isPlaying};var json=JsonUtility.ToJson(snapshot,true);SessionState.SetString(Data,json);File.WriteAllText(W+"out_main_camera_snapshot.json",json);File.Copy(snapshot.scene,W+"out_before_main_camera_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true);SessionState.SetString(Phase,"apply");if(EditorApplication.isPlaying)EditorApplication.isPlaying=false;else Apply();}catch(Exception e){Fail(e);}}
  static void StateChanged(PlayModeStateChange state){string p=SessionState.GetString(Phase,"");if(state==PlayModeStateChange.EnteredEditMode&&p=="apply")EditorApplication.delayCall+=Apply;if(state==PlayModeStateChange.EnteredPlayMode&&p=="verify")StartCheck();if(state==PlayModeStateChange.EnteredEditMode&&p=="finishEdit")EditorApplication.delayCall+=FinishEdit;}
  static void Apply(){if(SessionState.GetString(Phase,"")!="apply")return;SessionState.SetString(Phase,"applying");try{var snapshot=JsonUtility.FromJson<Snapshot>(SessionState.GetString(Data,""));var camera=Find();var scene=camera.gameObject.scene;EditorSceneManager.SaveScene(scene,W+"out_main_camera_edit_backup.unity",true);Undo.RecordObjects(new UnityEngine.Object[]{camera,camera.transform,camera.gameObject},"Set meadow main camera");camera.transform.SetPositionAndRotation(snapshot.position,snapshot.rotation);camera.transform.localScale=snapshot.scale;camera.fieldOfView=snapshot.fov;camera.nearClipPlane=snapshot.near;camera.farClipPlane=snapshot.far;camera.orthographic=snapshot.ortho;camera.orthographicSize=snapshot.orthoSize;camera.tag="MainCamera";camera.enabled=true;camera.targetDisplay=0;camera.depth=10;camera.rect=new Rect(0,0,1,1);camera.gameObject.SetActive(true);var data=camera.GetUniversalAdditionalCameraData();Undo.RecordObject(data,"Set base camera");data.renderType=CameraRenderType.Base;var listener=camera.GetComponent<AudioListener>();if(!listener)listener=Undo.AddComponent<AudioListener>(camera.gameObject);listener.enabled=true;
   foreach(var other in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).Where(c=>c!=camera)){Undo.RecordObject(other,"Disable previous camera");other.enabled=false;if(other.CompareTag("MainCamera")){Undo.RecordObject(other.gameObject,"Remove previous main tag");other.tag="Untagged";}EditorUtility.SetDirty(other);}
   foreach(var other in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<AudioListener>(true)).Where(a=>a!=listener)){Undo.RecordObject(other,"Disable previous listener");other.enabled=false;EditorUtility.SetDirty(other);}
   if(!camera.GetComponent<ArtStyleTest.OutMainCameraOwner>())Undo.AddComponent<ArtStyleTest.OutMainCameraOwner>(camera.gameObject);foreach(var o in new UnityEngine.Object[]{camera,camera.transform,camera.gameObject,data,listener})EditorUtility.SetDirty(o);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Saving scene failed");Selection.activeGameObject=camera.gameObject;File.WriteAllText(W+"out_main_camera_setup.txt","saved=True target=xiangjipingtai/Camera tag="+camera.tag+" position="+camera.transform.position.ToString("R")+" rotation="+camera.transform.rotation.eulerAngles.ToString("R")+" previousPlayMode="+snapshot.wasPlaying+" runtimeCheck=pending");SessionState.SetString(Phase,"verify");EditorApplication.isPlaying=true;
  }catch(Exception e){Fail(e);}}
  static void StartCheck(){started=EditorApplication.timeSinceStartup;EditorApplication.update-=Check;EditorApplication.update+=Check;}
  static void Check(){if(!EditorApplication.isPlaying)return;if(EditorApplication.timeSinceStartup-started<2||Time.time<.15f){if(EditorApplication.timeSinceStartup-started>30)Fail(new Exception("Runtime check timed out"));return;}EditorApplication.update-=Check;try{var camera=Find();var rendered=Camera.allCameras.Where(c=>c.cameraType==CameraType.Game&&!c.targetTexture&&c.targetDisplay==0&&c.GetUniversalAdditionalCameraData().renderType==CameraRenderType.Base).ToArray();bool main=Camera.main==camera;int listeners=UnityEngine.Object.FindObjectsOfType<AudioListener>().Count(a=>a.enabled);var snapshot=JsonUtility.FromJson<Snapshot>(SessionState.GetString(Data,""));float positionDelta=Vector3.Distance(camera.transform.position,snapshot.position),angleDelta=Quaternion.Angle(camera.transform.rotation,snapshot.rotation);File.AppendAllText(W+"out_main_camera_setup.txt","\nCamera.mainMatches="+main+" activeDisplay1BaseCameras="+rendered.Length+" activeAudioListeners="+listeners+" poseDistance="+positionDelta+" poseAngle="+angleDelta);if(!main||rendered.Length!=1||rendered[0]!=camera||listeners!=1||positionDelta>.001f||angleDelta>.01f)throw new Exception("Runtime camera verification failed");File.AppendAllText(W+"out_main_camera_setup.txt","\nverified=True");Selection.activeGameObject=camera.gameObject;if(snapshot.wasPlaying){SessionState.SetString(Phase,"");File.AppendAllText(W+"out_main_camera_setup.txt","\nleftPlaying=True completed=True");}else{SessionState.SetString(Phase,"finishEdit");EditorApplication.isPlaying=false;}}
   catch(Exception e){Fail(e);}}
  static void FinishEdit(){try{var c=Find();if(!c.enabled||!c.CompareTag("MainCamera"))throw new Exception("Camera did not persist after Play mode");Selection.activeGameObject=c.gameObject;SessionState.SetString(Phase,"");File.AppendAllText(W+"out_main_camera_setup.txt","\npersistedAfterPlay=True completed=True");}catch(Exception e){Fail(e);}}
  static void Fail(Exception e){EditorApplication.update-=Check;SessionState.SetString(Phase,"");File.AppendAllText(W+"out_main_camera_setup.txt","\nERROR "+e);Debug.LogException(e);}
 }
}
